function valuesOnlyOneHas(a: number[], b: number[]): number[][] {
  const only = (x: number[], y: number[]): number[] => {
    const out: number[] = [];
    for (const v of x) if (!y.includes(v) && !out.includes(v)) out.push(v);
    return out;
  };
  return [only(a, b), only(b, a)];
}

