class Solution:
    def valuesOnlyOneHas(self, a: List[int], b: List[int]) -> List[List[int]]:
        def only(x, y):
            out = []
            for v in x:
                if v not in y and v not in out:
                    out.append(v)
            return out
        return [only(a, b), only(b, a)]

